content.query:
SELECT TOP 10 rank, page_title, views, mobile_views
FROM dbo.vw_top_pages_daily
WHERE view_date = '2026-09-28'
ORDER BY rank;

CREATE VIEW dbo.vw_ops_run_log AS
SELECT * FROM OPENROWSET(
    BULK 'ops_run_log/', DATA_SOURCE = 'ds_gold', FORMAT = 'DELTA') AS r;
GO

SELECT * FROM dbo.vw_ops_run_log ORDER BY logged_at DESC;
